//! Native candidate custom errors share authoritative validation state.
use super::*;
fn start(source:&str)->(Document,Forms,Page){let mut d=crate::html::parse("<body><form id=form><input id=input name=q value=Seed><textarea id=area name=body>Body</textarea><select id=select name=choice><option value=ready>Ready</option></select><button id=button type=submit>Submit</button></form><input id=neighbor value=Neighbor></body>");d.scripting_enabled=true;let mut f=Forms::new(&d);let mut p=Page::new();let l=crate::navigation::address("https://control-custom.test/",&crate::navigation::Location::home()).unwrap();p.set_location(&l);p.set_resource_base(&l);let out=p.start(&mut d,&mut f,&[Script{node:0,label:"Native candidate custom errors".into(),source:source.into()}]);assert_eq!(out.errors,0,"{}",p.report());(d,f,p)}
#[test]
fn control_custom_validity_canonical_setters_messages_and_current_eligibility(){
 start(r#"var ids=['input','area','select','button'],classes=[HTMLInputElement,HTMLTextAreaElement,HTMLSelectElement,HTMLButtonElement];for(var i=0;i<ids.length;i++){var x=document.getElementById(ids[i]),m=classes[i].prototype.setCustomValidity,d=Object.getOwnPropertyDescriptor(classes[i].prototype,'setCustomValidity');if(!d||d.value!==m||!d.writable||!d.enumerable||!d.configurable||m.length!==1||m.name!=='setCustomValidity'||Object.prototype.hasOwnProperty.call(x,'setCustomValidity'))throw 'canonical setter';if(x.setCustomValidity('A\ud800z\r\nB\rC')!==undefined)throw 'setter result';var message=x.validationMessage;if(message.length!==7||message.charCodeAt(1)!==0xd800||message!=='A\ud800z\nB\nC'||x.checkValidity()!==false)throw 'custom invalid '+ids[i];x.disabled=true;if(x.validationMessage!==''||!x.checkValidity())throw 'barred custom';x.disabled=false;if(x.validationMessage!==message||x.checkValidity()!==false)throw 'restored custom';x.setCustomValidity('');if(x.validationMessage!==''||!x.checkValidity())throw 'cleared custom';}"#);
}
#[test]
fn control_custom_validity_form_and_native_submission_snapshots_include_errors(){
 let(mut d,mut f,mut p)=start("var form=document.getElementById('form'),x=document.getElementById('input'),area=document.getElementById('area'),order='';x.setCustomValidity('Input custom');area.setCustomValidity('Area custom');x.addEventListener('invalid',function(e){if(!e.isTrusted)throw 'trusted';order+='I';area.setCustomValidity('');});area.addEventListener('invalid',function(){order+='A';});if(form.checkValidity()!==false||order!=='IA')throw 'form snapshot';if(form.reportValidity()!==false||order!=='IAI')throw 'current form state';");let owner=(0..d.nodes.len()).find(|&n|d.attr(n,"id")==Some("form")).unwrap();p.begin_job();let(_,invalid,unhandled)=p.validate_native_submission(&mut d,&mut f,owner,None).unwrap();let input=(0..d.nodes.len()).find(|&n|d.attr(n,"id")==Some("input")).unwrap();assert!(invalid);assert_eq!(unhandled,Some(input));p.begin_job();p.runtime.execute("x.setCustomValidity('');if(!form.checkValidity())throw 'cleared aggregate';",&mut Bridge{doc:&mut d,forms:&mut f,state:&mut p.state}).unwrap();
}
#[test]
fn control_custom_validity_conversion_side_effects_and_concrete_brands(){
 start("var ids=['input','area','select','button'],classes=[HTMLInputElement,HTMLTextAreaElement,HTMLSelectElement,HTMLButtonElement];for(var i=0;i<ids.length;i++){var x=document.getElementById(ids[i]),method=classes[i].prototype.setCustomValidity,calls=0;for(var bad of [{},Object.create(classes[i].prototype),document.getElementById(ids[(i+1)%4])]){var denied=false;try{method.call(bad,{toString:function(){calls++;return 'bad';}});}catch(e){denied=e instanceof TypeError;}if(!denied||calls)throw 'brand before conversion';}x.setCustomValidity('Existing');for(var arg of [undefined,Symbol('bad')]){var denied=false;try{if(arg===undefined){method.call(x);}else{method.call(x,arg);}}catch(e){denied=e instanceof TypeError;}if(!denied||x.validationMessage!=='Existing')throw 'required argument and Symbol';}var effect={toString:function(){calls++;x.setAttribute('data-side-effect','kept');throw 'conversion marker';}},caught=false;try{x.setCustomValidity(effect);}catch(e){caught=e==='conversion marker';}if(!caught||calls!==1||x.getAttribute('data-side-effect')!=='kept'||x.validationMessage!=='Existing')throw 'conversion effects';x.setCustomValidity({toString:function(){calls++;return 'Converted';}});if(calls!==2||x.validationMessage!=='Converted')throw 'single DOMString conversion';x.setCustomValidity('');}");
}
#[test]
fn control_custom_validity_resource_refusals_preserve_error_and_recover(){
 for mode in 0..4{
  let(mut d,mut f,mut p)=start("var x=document.getElementById('input');x.setCustomValidity('Original');var watch=new MutationObserver(function(){});watch.observe(x,{attributes:true,childList:true,subtree:true});");let node=(0..d.nodes.len()).find(|&n|d.attr(n,"id")==Some("input")).unwrap();let object=node_handle(node);let before=(format!("{:?}",d.nodes),p.state.retained,p.state.dom_commits);let limit=p.state.retained_limit;p.begin_job();match mode{0=>p.state.host_work=0,1=>p.state.copy_work=0,2=>p.state.retained_limit=p.state.retained,_=>p.state.execution_deadline=Some(Instant::now())};let result=Bridge{doc:&mut d,forms:&mut f,state:&mut p.state}.control_custom_validity_call(object,&[Value::String("replacement".repeat(64))]);assert!(result.is_err(),"mode {mode}");assert_eq!((format!("{:?}",d.nodes),p.state.retained,p.state.dom_commits),before);assert_eq!(p.state.output_custom_errors.get(&object).unwrap().render_projection(),"Original");assert!(p.take_validation_report().is_none());p.state.retained_limit=limit;p.begin_job();p.state.copy_work=0;assert!(Bridge{doc:&mut d,forms:&mut f,state:&mut p.state}.control_validation_message(object).is_err());p.begin_job();p.runtime.execute("if(x.validationMessage!=='Original'||watch.takeRecords().length)throw 'atomic custom refusal';x.setCustomValidity('Recovered');if(x.validationMessage!=='Recovered'||x.checkValidity()!==false||watch.takeRecords().length)throw 'custom recovery';x.setCustomValidity('');if(!x.checkValidity())throw 'cleared recovery';",&mut Bridge{doc:&mut d,forms:&mut f,state:&mut p.state}).unwrap();
 }
}
#[test]
fn control_custom_validity_saved_setter_shadow_delete_restore_and_isolation(){
 start("var x=document.getElementById('input'),area=document.getElementById('area'),P=HTMLInputElement.prototype,d=Object.getOwnPropertyDescriptor(P,'setCustomValidity'),saved=d.value;Object.defineProperty(x,'setCustomValidity',{value:'own',configurable:true});saved.call(x,'Stored');if(x.setCustomValidity!=='own'||x.validationMessage!=='Stored'||area.validationMessage!=='')throw 'own shadow';delete x.setCustomValidity;Object.defineProperty(P,'setCustomValidity',{value:'prototype',configurable:true});saved.call(x,'Changed');if(x.setCustomValidity!=='prototype'||x.validationMessage!=='Changed')throw 'prototype shadow';delete P.setCustomValidity;if(x.setCustomValidity!==undefined)throw 'canonical deletion';saved.call(x,'');Object.defineProperty(P,'setCustomValidity',d);if(x.setCustomValidity!==saved||!x.checkValidity())throw 'canonical restore';");
}
#[test]
fn control_custom_validity_reset_and_lifecycle_refusals_keep_authoritative_error(){
 let(mut d,mut f,mut p)=start("var x=document.getElementById('input'),form=document.getElementById('form');x.value='Edited';x.setCustomValidity('Persistent');form.reset();if(x.value!=='Seed'||x.validationMessage!=='Persistent'||x.checkValidity()!==false)throw 'reset preserves custom error';var target=document.implementation.createHTMLDocument('target'),denied=false;try{target.adoptNode(x);}catch(e){denied=e instanceof DOMException&&e.name==='NotSupportedError';}if(!denied||x.ownerDocument!==document||x.parentNode!==form||x.validationMessage!=='Persistent')throw 'native lifecycle refusal';var fresh=document.createElement('input');fresh.setAttribute('type','hidden');fresh.setCustomValidity('Hidden custom');if(fresh.validationMessage!==''||!fresh.checkValidity())throw 'fresh barred storage';x.setCustomValidity('');if(!form.checkValidity())throw 'reset custom recovery';"); let before=format!("{:?}",d.nodes);p.begin_job();let error=p.runtime.execute("x.setCustomValidity('Clone persistent');form.cloneNode(true);",&mut Bridge{doc:&mut d,forms:&mut f,state:&mut p.state}).unwrap_err();assert!(error.contains("Cloning")||error.contains("not implemented"),"{error}");assert_eq!(format!("{:?}",d.nodes),before);let node=(0..d.nodes.len()).find(|&n|d.attr(n,"id")==Some("input")).unwrap();assert_eq!(p.state.output_custom_errors.get(&node_handle(node)).unwrap().render_projection(),"Clone persistent");p.begin_job();p.runtime.execute("if(x.validationMessage!=='Clone persistent'||x.checkValidity()!==false)throw 'clone preserves custom';x.setCustomValidity('');if(!form.checkValidity())throw 'clone refusal recovery';",&mut Bridge{doc:&mut d,forms:&mut f,state:&mut p.state}).unwrap();
}
#[test]
fn control_custom_validity_request_submit_novalidate_and_fresh_recovery(){
 start("var form=document.getElementById('form'),x=document.getElementById('input'),b=document.getElementById('button'),invalid=0,submitted=0;x.setCustomValidity('Stop');x.addEventListener('invalid',function(e){invalid++;e.preventDefault();});form.addEventListener('submit',function(e){if(!e.isTrusted||e.submitter!==b)throw 'trusted submission';submitted++;e.preventDefault();});form.requestSubmit(b);if(invalid!==1||submitted!==0)throw 'custom blocks request';form.noValidate=true;form.requestSubmit(b);if(invalid!==1||submitted!==1||form.checkValidity()!==false||invalid!==2)throw 'novalidate remains separate';x.setCustomValidity('');form.noValidate=false;form.requestSubmit(b);if(submitted!==2||invalid!==2)throw 'custom submit recovery';");
}
#[test]
fn control_custom_validity_saved_child_authority_and_inert_backend_preserve_conversion_effects(){
 let(mut d,mut f,mut p)=start("var x=document.getElementById('input'),frame=document.createElement('iframe');frame.hidden=true;document.body.appendChild(frame);var setter=frame.contentWindow.HTMLInputElement.prototype.setCustomValidity;setter.call(x,'Saved');var inert=document.implementation.createHTMLDocument('inert').createElement('input'),calls=0,denied=false;try{setter.call(inert,{toString:function(){calls++;return 'bad';}});}catch(e){denied=e instanceof frame.contentWindow.DOMException&&e.name==='NotSupportedError';}if(!denied||calls!==1)throw 'inert conversion order '+denied+'/'+calls;");p.set_location(&crate::navigation::address("https://foreign-custom.test/",&crate::navigation::Location::home()).unwrap());p.begin_job();let error=p.runtime.execute("setter.call(x,{toString:function(){calls++;return 'bad';}});",&mut Bridge{doc:&mut d,forms:&mut f,state:&mut p.state}).unwrap_err();assert!(error.contains("origin")||error.contains("Security"),"{error}");p.set_location(&crate::navigation::address("https://control-custom.test/",&crate::navigation::Location::home()).unwrap());p.begin_job();p.runtime.execute("if(calls!==1||x.validationMessage!=='Saved')throw 'authority preserves state';setter.call(x,'');if(!x.checkValidity())throw 'saved recovery';",&mut Bridge{doc:&mut d,forms:&mut f,state:&mut p.state}).unwrap();
}
#[test]
fn control_custom_validity_fatal_invalid_listener_keeps_committed_custom_error(){
 let(mut d,mut f,mut p)=start("var x=document.getElementById('input'),area=document.getElementById('area');x.setCustomValidity('Initial');area.setCustomValidity('Nested');var listener=function(){area.checkValidity();x.setCustomValidity('Committed');for(var i=0;i<10000;i++){x.getAttribute('id');}};x.addEventListener('invalid',listener);");let node=(0..d.nodes.len()).find(|&n|d.attr(n,"id")==Some("input")).unwrap();p.begin_job();p.state.host_work=2000;let error=p.runtime.execute("x.checkValidity();",&mut Bridge{doc:&mut d,forms:&mut f,state:&mut p.state}).unwrap_err();assert!(error.contains("work")||error.contains("allowance"),"{error}");assert_eq!(p.state.output_custom_errors.get(&node_handle(node)).unwrap().render_projection(),"Committed");assert!(p.state.form_validations.is_empty()&&p.state.synthetic_dispatches.is_empty()&&p.state.form_requests.is_empty());p.begin_job();p.runtime.execute("x.removeEventListener('invalid',listener);if(x.validationMessage!=='Committed'||x.checkValidity()!==false)throw 'committed custom survives';x.setCustomValidity('');area.setCustomValidity('');if(!document.getElementById('form').checkValidity())throw 'fatal fresh recovery';",&mut Bridge{doc:&mut d,forms:&mut f,state:&mut p.state}).unwrap();
}
